<?php
declare(strict_types=1);namespace Atlas\Platform\Workflows\Authoring;use Atlas\Platform\Core\Audit\AuditRecorder;use RuntimeException;final class WordPressWorkflowDraftRepository implements WorkflowDraftRepository{public function __construct(private object$db,private AuditRecorder$audit){}public function create(string$key,string$fingerprint,array$d,int$userId):array{$ops=$this->db->prefix.'atlas_workflow_draft_operations';$existing=$this->db->get_row($this->db->prepare("SELECT fingerprint,workflow_id,workflow_version_id FROM `{$ops}` WHERE operation_key=%s",$key),ARRAY_A);if(is_array($existing)){if(!hash_equals((string)$existing['fingerprint'],$fingerprint)){throw new RuntimeException('The idempotency key was already used for a different request.');}return['workflow_id'=>$existing['workflow_id'],'workflow_version_id'=>$existing['workflow_version_id'],'status'=>'draft','replayed'=>true];}$workflow=wp_generate_uuid_4();$version=wp_generate_uuid_4();$now=current_time('mysql',true);$this->query('START TRANSACTION');try{$this->insert($this->db->prefix.'atlas_workflows',['id'=>$workflow,'scope'=>$d['scope'],'scope_key'=>$d['scope_key'],'organization_id'=>$d['organization_id'],'slug'=>$d['slug'],'current_version_id'=>null,'created_at'=>$now,'updated_at'=>$now]);$this->insert($this->db->prefix.'atlas_workflow_versions',['id'=>$version,'workflow_id'=>$workflow,'version_number'=>1,'title'=>$d['title'],'summary'=>$d['summary'],'status'=>'draft','source_resource_version_id'=>$d['source_resource_version_id']?:null,'created_by'=>$userId,'created_at'=>$now]);foreach($d['steps']as$step){$this->insert($this->db->prefix.'atlas_workflow_steps',['id'=>wp_generate_uuid_4(),'workflow_version_id'=>$version,'step_position'=>$step['position'],'title'=>$step['title'],'instruction'=>$step['instruction'],'requirement_text'=>$step['requirement'],'warning_text'=>$step['warning']?:null,'related_resource_id'=>$step['related_resource_id']?:null]);}$this->insert($ops,['operation_key'=>$key,'fingerprint'=>$fingerprint,'workflow_id'=>$workflow,'workflow_version_id'=>$version,'created_at'=>$now]);$this->audit->record('workflow.draft_created','workflows',$userId,$d['organization_id'],'workflow',$workflow,['workflow_version_id'=>$version,'step_count'=>count($d['steps'])]);$this->query('COMMIT');}catch(\Throwable$failure){$this->query('ROLLBACK');throw$failure;}return['workflow_id'=>$workflow,'workflow_version_id'=>$version,'status'=>'draft','replayed'=>false];}private function insert(string$table,array$data):void{if($this->db->insert($table,$data)===false){throw new RuntimeException('Workflow draft could not be persisted.');}}private function query(string$sql):void{if($this->db->query($sql)===false){throw new RuntimeException('Workflow draft transaction failed.');}}}
